import pytest
from unittest.mock import MagicMock, patch
from requests.structures import *

def test_caseinsensitivedict_eq():
    assert CaseInsensitiveDict({'foo': 'bar'}) == {'foo': 'bar'}
    assert CaseInsensitiveDict({'FOO': 'BAR'}) == {'FOO': 'BAR'}

def test_caseinsensitivedict_setitem():
    obj = CaseInsensitiveDict()
    obj['KEY'] = 'val'
    assert obj['key'] == 'val'

def test_lookupdict_getitem():
    assert LookupDict()[None] == None

def test_caseinsensitivedict_lower_items():
    assert list(CaseInsensitiveDict().lower_items()) == []
    assert list(CaseInsensitiveDict({'KEY': 'VALUE'}).lower_items()) == [('key', 'VALUE')]

def test_caseinsensitivedict_getitem():
    obj = CaseInsensitiveDict()
    obj["Key"] = "Value"
    assert obj["KEY"] == "Value"

def test_caseinsensitivedict_delitem():
    obj = CaseInsensitiveDict({'key': 'value'})
    del obj['key']
    assert 'key' not in obj

def test_caseinsensitivedict_iter():
    assert list(CaseInsensitiveDict({'a': 1, 'b': 2})) == ['a', 'b']
    assert list(CaseInsensitiveDict({})) == []
    assert list(CaseInsensitiveDict({'c': 3, 'd': 4, 'e': 5})) == ['c', 'd', 'e']

def test_caseinsensitivedict_len():
    assert len(CaseInsensitiveDict({'a': 1, 'b': 2})) == 2
    assert len(CaseInsensitiveDict({'a': 1, 'b': 2, 'c': 3})) == 3
    assert len(CaseInsensitiveDict({'a': 1, 'b': 2, 'c': 3, 'd': 4})) == 4

def test_caseinsensitivedict_copy():
    assert CaseInsensitiveDict({'key': 'value'}).copy() == {'key': 'value'}

def test_caseinsensitivedict_repr():
    assert repr(CaseInsensitiveDict({"key": "value"})) == "{'key': 'value'}"

def test_lookupdict_repr():
    obj = LookupDict(name="test_name")
    assert repr(obj) == "<lookup 'test_name'>"

def test_lookupdict_get():
    assert LookupDict().get(1) == None
    assert LookupDict().get(1) == LookupDict().get(1)

def test_caseinsensitivedict_init():
    assert CaseInsensitiveDict({'x': 1}) == {'x': 1}
    assert CaseInsensitiveDict({'x': 1}).get('x') == 1
    assert CaseInsensitiveDict({'x': 1}).get('y') == None
    assert CaseInsensitiveDict({'x': 1}).get('y', 2) == 2

def test_lookupdict_init():
    assert LookupDict().name == None
    assert LookupDict().get('name') == None
